/* best-fit build, every 3rd freed plus some neighbours (varied holes), 120k mixed best-fit ops
 * Phase 1: 306000 mallocs under BEST_FIT; phase 2: free every block i with i % MOD == REM
 * (plus i % MOD == REM2 with probability EXTRA_PM/1000) -> at least 100,000 free blocks;
 * phase 3 under BEST_FIT: 120000 calls, malloc with probability 600/1000 (n in 1..600) else free a random live block; then heap dump + leak report.
 * Generated by gen/perf_tests.py; expected output from the Python reference model. */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "myalloc.h"

#ifndef NBUILD
#define NBUILD 306000
#endif
#ifndef NOPS
#define NOPS 120000
#endif
#define SEED 13ull
#define BUILD_POLICY BEST_FIT
#define OPS_POLICY BEST_FIT
#define MINB 1
#define SPANB 300
#define MOD 3
#define REM 1
#define REM2 2
#define EXTRA_PM 300
#define MODE 0
#define PM 600
#define MEVERY 100
#define MINO 1
#define SPANO 600

#define NMAX (NBUILD + NOPS + NBUILD / MEVERY + 16)
static void *P[NMAX];
static int LIVE[NMAX];
static int NL;
static uint64_t S = SEED;

static uint64_t rnd(void)
{
    S ^= S << 13;
    S ^= S >> 7;
    S ^= S << 17;
    return S;
}

int main(void)
{
    int nid = 0;
    my_set_policy(BUILD_POLICY);
    for (int i = 0; i < NBUILD; i++) {
        size_t n = MINB + rnd() % SPANB;
        P[nid] = my_malloc(n);
        ((unsigned char *)P[nid])[0] = 1;
        nid++;
    }
    for (int i = 0; i < NBUILD; i++) {
        int fr = (i % MOD == REM) || (EXTRA_PM && i % MOD == REM2 && (int)(rnd() % 1000) < EXTRA_PM);
        if (fr)
            my_free(P[i]);
        else
            LIVE[NL++] = i;
    }
    my_set_policy(OPS_POLICY);
    if (MODE == 0) {
        for (int k = 0; k < NOPS; k++) {
            if (NL == 0 || (int)(rnd() % 1000) < PM) {
                size_t n = MINO + rnd() % SPANO;
                P[nid] = my_malloc(n);
                LIVE[NL++] = nid++;
            } else {
                int j = (int)(rnd() % (uint64_t)NL);
                int id = LIVE[j];
                LIVE[j] = LIVE[--NL];
                my_free(P[id]);
            }
        }
    } else {
        int cnt = 0;
        while (NL > 0) {
            int j = (int)(rnd() % (uint64_t)NL);
            int id = LIVE[j];
            LIVE[j] = LIVE[--NL];
            my_free(P[id]);
            if (++cnt % MEVERY == 0) {
                size_t n = MINO + rnd() % SPANO;
                P[nid++] = my_malloc(n);
            }
        }
    }
    my_heap_dump();
    my_leak_report();
    return 0;
}
